// The parts of the crew screen for an analog test such as NASA's HERA: the Analog test card in Settings (the drill
// switch and what the alert log keeps), the DRILL tag, what each message says about its acknowledgement, the
// workload rating on the Bedford scale, and their "?" cards. The rules live in src/drill.js and src/alert-log.js;
// src/crew.js places these parts on the screen.
// Code generated by Claude (Anthropic), an AI system.
import { h, btn, supIcon } from './support.js';
import { DRILL_RULES, DRILL_SOURCES, DRILL_WORDS } from './drill.js';
import { BEDFORD, WORKLOAD_RULES, bedfordChoices, bedfordText } from './alert-log.js';

const two = (n) => String(n).padStart(2, '0');
const doy = (d) => Math.floor((Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()) - Date.UTC(d.getUTCFullYear(), 0, 0)) / 86400000);
const gmt = (t) => { const d = new Date(t); return `GMT ${doy(d)}/${two(d.getUTCHours())}:${two(d.getUTCMinutes())}:${two(d.getUTCSeconds())}`; };
const link = (s) => h('a', { href: s.url, target: '_blank', rel: 'noopener' }, s.name);
const sources = (list) => h('p', { class: 'note' }, list.length > 1 ? 'Sources: ' : 'Source: ', ...list.flatMap((s, i) => [i ? '; ' : '', link(s)]));

// The "?" cards, in the shape of src/tips.js (title and lines).
export const ANALOG_TIPS = {
  drill: { title: 'Drill', lines: [
    'A drill is on: the crew practises an emergency. A NASA presentation on the HERA analog lists medical drills and emergency drills among the mission tasks (Vessey and others, 2017).',
    'Alarms sound and go to your crewmates and the doctor as usual, with the word DRILL. Drill readings never count in your levels, your medical record or the summaries for the doctor.',
    `It ends with "End the drill", by itself after ${DRILL_RULES.maxMinutes} minutes (a draft), and at sign-out. ${DRILL_WORDS.emergency}`,
  ] },
  alertlog: { title: 'Alert log', lines: [
    'When an alert shows on your screen, is acknowledged (Mark as read, Mark all as read, the Messages key, Silence, Silence all sounds), clears, or is called off as a false alarm, that step is saved in your record: one entry per alert and step, with no text of the alert.',
    'So, with the station server, every screen where you are signed in shows the same read and acknowledged state within 15 seconds, and an acknowledged alarm does not sound there again. A copy without the server keeps them in this browser only. Your crewmates never see these entries.',
    'The time to acknowledge is worked out from them. For an analog test the technical view exports them for all subjects, by id only, without any alert about the mind, the cycle, symptoms or medicines.',
  ] },
  workload: { title: 'Workload rating', lines: [
    'The Bedford workload scale: NASA asks that crew interfaces result in a rating of 3 or less for nominal tasks and 6 or less under degraded system conditions (NASA-STD-3001 Vol 2, 5007).',
    'Answer the three questions from the bottom up, as the scale asks, then pick the level whose words fit best. Optional, and only for urgent alarms (a draft).',
    'Saved in your record and counted, by id only, in the study export of the analog test.',
  ] },
};

// The tag on the status line while a drill runs: a mode marker like "Example data", with its own icon and word.
export const drillTag = () => h('span', { class: 'tag example drill', 'data-tip': 't:drill', 'data-tip-press': '', 'data-fk': 'tag:drill', tabindex: '0' }, supIcon('flag', { size: 16 }), DRILL_WORDS.tag);

// Settings, "Analog test": the drill switch, the end button while it runs, and what the alert log keeps.
export function analogCard({ drill = null, left = 0, onDrill, switchRow, cornerTip }) {
  return h('section', { class: 'card', id: 'analog-card' },
    cornerTip ? cornerTip('t:alertlog', 'the alert log') : null,
    h('h2', {}, 'Analog test'),
    switchRow('st-drill', DRILL_WORDS.switchLabel, DRILL_WORDS.switchText, Boolean(drill), (on) => onDrill(on)),
    drill ? h('p', { class: 'note', role: 'status' }, supIcon('flag', { size: 16 }), ` DRILL in progress since ${gmt(drill.since)}; it ends by itself in ${left} min. ${DRILL_WORDS.emergency}`) : null,
    h('p', { class: 'muted' }, 'Alert log: each alert\'s steps (shown, acknowledged, read, cleared, false alarm, workload) are saved in your record, one entry per alert and step, so with the station server your other screens show the same and an acknowledged alarm does not sound there again. Your crewmates never see them.'),
    sources(DRILL_SOURCES));
}

// What one message says about its acknowledgement (Appendix F.6.4 f asks for the acknowledge state of each event).
const HOW = { 'mark-read': 'Mark as read', 'mark-all-read': 'Mark all as read', 'messages-key': 'the Messages key', 'banner-silence': 'Silence', 'silence-all': 'Silence all sounds', 'false-alarm': 'I am okay: false alarm' };
export function ackText(s) {
  if (!s || s.ackAt === undefined) return 'Not acknowledged yet.';
  const after = s.timeToAck === null || s.timeToAck === undefined ? '' : `, ${s.timeToAck < 60 ? `${s.timeToAck} s` : `${Math.floor(s.timeToAck / 60)} min ${Math.round(s.timeToAck % 60)} s`} after it showed`;
  return `Acknowledged ${gmt(s.ackAt)}${after}${s.ackHow && HOW[s.ackHow] ? ` (${HOW[s.ackHow]})` : ''}.${s.rating ? ` Workload rated ${s.rating} of 10.` : ''}`;
}

// The Bedford scale as NASA's figure has it: the three questions from the bottom up, then the levels of the group they
// lead to. onSave(n) saves the chosen level; nothing is saved before that.
export function workloadForm({ onSave }) {
  const answers = [];
  let chosen = null;
  const host = h('div', { class: 'workload' });
  const draw = (focusSel = null) => {
    const { next, levels } = bedfordChoices(answers);
    const asked = BEDFORD.questions.slice(0, answers.length + (next ? 1 : 0));
    host.replaceChildren(
      h('p', {}, `The task: ${BEDFORD.task}. Answer from the first question down; each answer opens the next, as the scale asks.`),
      ...asked.map((q, i) => h('div', { class: 'switch-row', role: 'group', 'aria-labelledby': `wl-q-${q.id}` },
        h('span', { class: 'label', id: `wl-q-${q.id}` }, h('span', {}, `${i + 1}. ${q.text}`)),
        h('div', { class: 'seg small' }, ...[[true, 'Yes'], [false, 'No']].map(([v, word]) => h('button', {
          type: 'button', 'aria-pressed': String(answers[i] === v), 'data-fk': `wl:${q.id}:${word}`,
          onclick: () => {
            answers.length = i;
            answers.push(v);
            const nx = bedfordChoices(answers);
            chosen = nx.levels.length === 1 ? nx.levels[0] : null; // "No" to the first question leads to 10 alone
            draw(nx.next ? `[data-fk="wl:${nx.next.id}:Yes"]` : chosen ? '[data-fk="wl:save"]' : '[data-fk^="wl:level:"]');
          },
        }, answers[i] === v ? supIcon('check', { size: 14 }) : null, word))))),
      levels.length ? h('div', {},
        h('p', { id: 'wl-levels-q' }, levels.length === 1 ? 'This answer leads to one level:' : 'Choose the level whose words fit best:'),
        // The same list of steps as the energy question of the check-in (index.html .seg-list).
        h('div', { class: 'seg seg-list', role: 'group', 'aria-labelledby': 'wl-levels-q' }, ...levels.map((n) => h('button', {
          type: 'button', 'aria-pressed': String(chosen === n), 'data-fk': `wl:level:${n}`,
          onclick: () => { chosen = n; draw(`[data-fk="wl:level:${n}"]`); },
        }, h('span', { class: 'step' }, String(n)), bedfordText(n))))) : null,
      levels.length ? h('div', { class: 'actions' }, btn('primary', chosen ? `Save the rating ${chosen}` : 'Save the rating', () => { if (chosen) onSave(chosen); else { const f = host.querySelector('[data-fk^="wl:level:"]'); if (f) f.focus(); } }, 'check', { 'data-fk': 'wl:save', 'aria-disabled': chosen ? null : 'true' })) : null,
      h('p', { class: 'note' }, `NASA-STD-3001 Vol 2 [V2 5007]: ${BEDFORD.limits.nominal} or less for nominal tasks, ${BEDFORD.limits.degraded} or less under degraded system conditions. The scale's own words were written for pilots. ${WORKLOAD_RULES.note}`),
      sources(BEDFORD.sources));
    if (focusSel) { const el = host.querySelector(focusSel); if (el) el.focus(); }
  };
  draw();
  return host;
}
